+    int toUpperCaseEx(int ch) {
+        int mapChar = ch;
+        int val = getProperties(ch);
+
+        if ((val & $$maskUpperCase) != 0) {
+            if ((val & $$maskCaseOffset) != $$maskCaseOffset) {
+                int offset = val  << $$shiftCaseOffsetSign >> ($$shiftCaseOffsetSign+$$shiftCaseOffset);
+                if (offset != -1) { // excludes special case map
+                    mapChar =  ch - offset;
+                }
+            }
+            else {
+                mapChar = Character.ERROR;
+            }
+        }
+        return mapChar;
+    }
+
+    @Stable
+    static char[] sharpsMap = new char[] {'S', 'S'};
+
+    char[] toUpperCaseCharArray(int ch) {
+        if (ch == 0x1DF95) {
+            // LATIN SMALL LIGATURE LONG S WITH DESCENDER S
+            // same special case map as sharp S
+            return sharpsMap;
+        } else {
+            return Character.toChars(ch);
+        }
+    }
